
.char-row {
  border: 1px solid var(--c-border);
  border-radius: 8px;
  margin-bottom: 8px;
  background: var(--c-surface);
  overflow: hidden;
  transition: background 0.2s;

  &:hover {
    background: var(--c-surface-hover);
  }
}

.char-head {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 12px;
  background: none;
  border: none;
  color: var(--c-text);
  cursor: pointer;
  font-family: var(--font-family);
  font-size: 14px;
  text-align: left;
}

.char-avatar {
  width: 46px;
  height: 46px;
  border-radius: 50%;
  border: 2px solid var(--c-primary);
  background: linear-gradient(135deg, #3a3a42, #232326);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  flex-shrink: 0;

  .avatar-text {
    font-size: 21px;
    color: var(--c-primary);
  }

  img {
    width: 100%;
    height: 100%;
    object-fit: cover;
  }
}

.char-name {
  font-weight: 700;
  font-size: 18px;
  min-width: 56px;
  color: var(--c-primary);
}

.char-stage {
  font-size: 13px;
  color: var(--c-love);
  min-width: 44px;
}

.bar-block {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.bar-label {
  font-size: 13px;
  color: var(--c-text-muted);
  flex-shrink: 0;
}

.char-bar {
  flex: 1;
  height: 9px;
  border-radius: 5px;
  background: rgba(255, 255, 255, 0.1);
  overflow: hidden;
  min-width: 0;
}

.love-bar .bar-fill {
  background: linear-gradient(90deg, #c98a8a, var(--c-love));
}

.desire-bar .bar-fill {
  background: linear-gradient(90deg, #a84844, var(--c-accent));
}

.bar-num {
  font-size: 14px;
  color: var(--c-text);
  min-width: 28px;
  text-align: right;
  flex-shrink: 0;
}

.char-state {
  font-size: 13px;
  color: var(--c-text-muted);
  min-width: 46px;
  text-align: right;
  flex-shrink: 0;
}

.state-情动,
.state-娇喘 {
  color: var(--c-accent);
}

.state-高潮余韵 {
  color: var(--c-love);
}

.state-熟睡 {
  color: #7ba7d9;
}

.char-arrow {
  color: var(--c-text-muted);
  font-size: 12px;
  flex-shrink: 0;
}

.char-detail {
  display: flex;
  gap: 16px;
  padding: 12px;
  border-top: 1px solid var(--c-border);
}

.detail-portrait {
  width: 120px;
  height: 160px;
  border-radius: 8px;
  border: 1px solid var(--c-primary);
  background: linear-gradient(160deg, #3a3a44, #202024);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  flex-shrink: 0;

  .portrait-text {
    font-size: 44px;
    color: var(--c-primary);
  }

  img {
    width: 100%;
    height: 100%;
    object-fit: cover;
  }
}

.detail-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4px;
  justify-content: center;
}

.detail-row {
  display: flex;
  justify-content: space-between;
  padding: 4px 0;
  font-size: 14px;
  border-bottom: 1px dashed rgba(255, 255, 255, 0.06);

  &:last-child {
    border-bottom: none;
  }
}

.detail-label {
  color: var(--c-text-muted);
  flex-shrink: 0;
  margin-right: 12px;
}

.detail-value {
  color: var(--c-text);
  text-align: right;
}

.state-text-情动,
.state-text-娇喘 {
  color: var(--c-accent);
}

.state-text-高潮余韵 {
  color: var(--c-love);
}

.state-text-熟睡 {
  color: #7ba7d9;
}
