
.status-bar {
  max-width: 920px;
  margin: 0 auto;
  padding: 12px;
  background: var(--c-background);
  border: 1px solid var(--c-primary);
  border-radius: 10px;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.5);
}

.world-bar {
  display: flex;
  gap: 20px;
  padding: 4px 8px 10px;
  font-size: 14px;
  color: var(--c-text-muted);
  border-bottom: 1px dashed var(--c-border);
  margin-bottom: 10px;
}
